export function renderChapters(stations,allFeatures){return stations.map((s,i)=>{
 const final=i===stations.length-1;
 return `<section class="chapter ${s.mirror?'mirror':''} ${i===0?'is-active':''}" id="${s.id}" aria-labelledby="title-${s.id}"><div class="chapter-inner"><p class="eyebrow">${s.kicker}</p><${i?'h2':'h1'} id="title-${s.id}">${s.title}</${i?'h2':'h1'}>${s.feature?`<p class="station-intro">${s.feature.intro}</p>`:''}<p class="chapter-desc">${s.desc}</p>${i===0?`<div class="hero-actions"><a href="#stop-assistant" class="primary">شروع کاوش <span>←</span></a><button class="text-button" data-library>فهرست همه امکانات ↗</button></div><p class="concept-label"><i></i>۱۹ امکان پیشنهادی · هر ایستگاه، یک عکس و یک توضیح</p><div class="scroll-cue"><span>↔</span>اسکرول کنید یا با کلیدهای چپ و راست حرکت کنید</div>`:s.feature?`<div class="station-facts"><span>فاز پیشنهادی ${new Intl.NumberFormat('fa-IR').format(s.feature.phase)}</span><span>${s.feature.tag}</span></div><button class="feature-chip station-detail" data-feature="${s.feature.id}">سناریو و پیش‌نیاز اجرا <span>↗</span></button><div class="world-meta"><span class="world-index">${s.num}</span><div><p>${s.feature.tag}</p><small>${s.en}</small></div></div>`:'<p class="connected-note">نقطه‌های شبکه را لمس کنید و ارتباط امکانات را کشف کنید.</p>'}</div>${final?'<div class="network-wrap"><svg id="city-network" viewBox="0 0 640 560" role="group" aria-label="شبکه تعاملی ارتباط خدمات شهر هوشمند"></svg><p class="network-help">شبکه مفهومی خدمات · هر نقطه یک امکان برای کشف</p></div>':`<div class="station-caption"><span>${s.place}</span><small>${s.feature?'تصویر برای توضیح ایده است؛ قابلیت پیشنهادی است.':'عکس واقعی شاهرود و پیرامون'}</small></div>`}</section>`;
 }).join('');}
